src/hazard/classify.ts.source:
/**
 * The hazard classifier. Given a parsed schedule, a zone, and a
 * wall-clock window, it enumerates the intended firings, resolves
 * each through the timezone engine, and reports every hazard: skipped
 * and doubled firings for point schedules, interval drift for
 * interval-like schedules, count anomalies for calendar days that do
 * not exist, and a zone-unstable label for predicted regions.
 *
 * Enumeration and resolution stay separate (phases 3 and 2); this
 * module is the join between them and owns no calendar or offset math
 * of its own.
 */

import { parse, type CronAst } from '../cron/index';
import { wallMillisFromFields, type TzBackend } from '../tz/index';
import { countAnomalyHazards } from './count-anomaly';
import { intervalDriftHazards } from './interval-drift';
import { perFiringHazards } from './per-firing';
import { enumerateFirings, resolveFirings } from './resolve-firings';
import { severityRank } from './severity';
import { zoneUnstableHazards } from './zone-unstable';
import type { ClassifyInput, Hazard } from './types';

/**
 * True when the schedule fires several times an hour at a fixed
 * cadence: the minute field literally begins with an asterisk (a
 * wildcard or step) and matches more than one minute. Such schedules
 * report transition effects as INTERVAL_DRIFT rather than as a run of
 * skipped or doubled firings.
 */
export function isIntervalLike(ast: CronAst): boolean {
  return ast.minute.startsWithAsterisk && ast.minute.values.length > 1;
}

function sortHazards(hazards: Hazard[]): Hazard[] {
  return [...hazards].sort((a, b) => {
    const bySeverity = severityRank(b.severity) - severityRank(a.severity);
    if (bySeverity !== 0) {
      return bySeverity;
    }
    return wallMillisFromFields(a.intendedLocal) - wallMillisFromFields(b.intendedLocal);
  });
}

/**
 * Classifies every timezone hazard for one schedule in one zone over
 * the window. The ast must already be parsed under the given dialect.
 */
export function classifyHazards(ast: CronAst, backend: TzBackend, input: ClassifyInput): Hazard[] {
  const idempotent = input.idempotent ?? false;
  const firings = enumerateFirings(ast, input.zone, input.from, input.to);
  const hazards: Hazard[] = [];

  if (isIntervalLike(ast)) {
    hazards.push(
      ...intervalDriftHazards(
        firings,
        input.expression,
        input.dialect,
        input.zone,
        input.from,
        input.to,
        backend,
        idempotent,
      ),
    );
  } else {
    const resolved = resolveFirings(firings, input.zone, backend);
    hazards.push(
      ...perFiringHazards(resolved, input.expression, input.dialect, input.zone, backend, idempotent),
    );
    hazards.push(
      ...countAnomalyHazards(resolved, input.expression, input.dialect, input.zone, backend, idempotent),
    );
  }

  hazards.push(
    ...zoneUnstableHazards(firings, input.expression, input.dialect, input.zone, input.zoneinfoRoot, idempotent),
  );
  return sortHazards(hazards);
}

/**
 * Convenience entry point that parses the expression and classifies
 * in one call. Throws when the expression does not parse under the
 * dialect, with the first located error.
 */
export function classifyExpression(input: ClassifyInput, backend: TzBackend): Hazard[] {
  const parsed = parse(input.expression, input.dialect);
  if (!parsed.ok) {
    const first = parsed.errors[0];
    throw new Error(
      `cannot classify: "${input.expression}" is invalid ${input.dialect}` +
        (first === undefined ? '' : ` at offset ${first.offset}: ${first.reason}`),
    );
  }
  return classifyHazards(parsed.ast, backend, input);
}

src/hazard/count-anomaly.ts.source:
/**
 * COUNT_ANOMALY: a calendar day whose firing count differs from the
 * schedule's modal daily count because the day itself is structurally
 * anomalous, a calendar day that does not exist (every wall time is
 * skipped) or, in principle, one that is fully duplicated. This is
 * the safety net that catches a whole missing day, which a per-firing
 * check reports only as one more skipped firing among many.
 */

import { resolveWallClock, type TzBackend } from '../tz/index';
import type { DialectId, LocalFiring } from '../cron/index';
import { makeHazard } from './build-hazard';
import type { ResolvedFiring } from './resolve-firings';
import type { CountAnomalyDetail, Hazard } from './types';

interface DayGroup {
  local: LocalFiring;
  firingCount: number;
}

function dayKey(local: LocalFiring): string {
  return `${local.year}-${local.month}-${local.day}`;
}

function modalCount(groups: DayGroup[]): number {
  const counts = new Map<number, number>();
  for (const group of groups) {
    counts.set(group.firingCount, (counts.get(group.firingCount) ?? 0) + 1);
  }
  let best = 0;
  let bestFreq = -1;
  for (const [count, freq] of counts) {
    if (freq > bestFreq) {
      best = count;
      bestFreq = freq;
    }
  }
  return best;
}

function structuralReason(
  local: LocalFiring,
  zone: string,
  backend: TzBackend,
): CountAnomalyDetail['reason'] | null {
  const noon = { year: local.year, month: local.month, day: local.day, hour: 12, minute: 0, second: 0 };
  const resolution = resolveWallClock(noon, zone, backend);
  if (resolution.kind === 'nonexistent') {
    return 'phantom-day';
  }
  if (resolution.kind === 'ambiguous') {
    return 'duplicated-day';
  }
  return null;
}

/** Emits COUNT_ANOMALY for structurally anomalous calendar days. */
export function countAnomalyHazards(
  resolved: ResolvedFiring[],
  expression: string,
  dialect: DialectId,
  zone: string,
  backend: TzBackend,
  idempotent: boolean,
): Hazard[] {
  const groups = new Map<string, DayGroup>();
  for (const firing of resolved) {
    const key = dayKey(firing.local);
    const midnight = {
      year: firing.local.year,
      month: firing.local.month,
      day: firing.local.day,
      hour: 0,
      minute: 0,
      second: 0,
    };
    const group = groups.get(key) ?? { local: midnight, firingCount: 0 };
    if (firing.resolution.kind !== 'nonexistent') {
      group.firingCount += 1;
    }
    groups.set(key, group);
  }

  const list = [...groups.values()];
  const modal = modalCount(list);
  const hazards: Hazard[] = [];
  for (const group of list) {
    if (group.firingCount === modal) {
      continue;
    }
    const reason = structuralReason(group.local, zone, backend);
    if (reason === null) {
      continue;
    }
    hazards.push(
      makeHazard({
        kind: 'COUNT_ANOMALY',
        expression,
        dialect,
        zone,
        intendedLocal: group.local,
        instants: [],
        causingTransition: null,
        idempotent,
        detail: {
          kind: 'COUNT_ANOMALY',
          count: { dayFiringCount: group.firingCount, modalCount: modal, reason },
        },
      }),
    );
  }
  return hazards;
}

src/hazard/interval-drift.ts.source:
/**
 * INTERVAL_DRIFT for interval-like schedules (a wildcard or step
 * minute field firing several times an hour). Such a schedule neither
 * skips nor doubles a distinct job; instead its real inter-firing
 * interval stretches across a transition. Each transition that the
 * schedule fires around produces one drift hazard.
 *
 * The nominal cadence is the modal spacing between consecutive
 * firings away from a transition. Across a transition of magnitude D,
 * the affected interval grows to cadence plus |D|: on spring-forward
 * this is the wall-clock gap with no firing, on fall-back it is the
 * real-time gap between the last pre-transition firing and the first
 * post-transition firing. See DECISIONS.md, phase 4.
 */

import { wallMillisFromFields, type TzBackend } from '../tz/index';
import type { DialectId, LocalFiring } from '../cron/index';
import { makeHazard } from './build-hazard';
import { windowTransitions } from './transitions';
import type { Hazard } from './types';

const THREE_HOURS_MILLIS = 3 * 3_600_000;

/** Modal positive spacing between consecutive firings, or null. */
function nominalCadence(wallMillis: number[]): number | null {
  if (wallMillis.length < 2) {
    return null;
  }
  const counts = new Map<number, number>();
  for (let i = 1; i < wallMillis.length; i += 1) {
    const diff = (wallMillis[i] ?? 0) - (wallMillis[i - 1] ?? 0);
    if (diff > 0) {
      counts.set(diff, (counts.get(diff) ?? 0) + 1);
    }
  }
  let best: number | null = null;
  let bestCount = 0;
  for (const [diff, count] of counts) {
    if (count > bestCount || (count === bestCount && best !== null && diff < best)) {
      best = diff;
      bestCount = count;
    }
  }
  return best;
}

interface Bracket {
  before: LocalFiring;
  after: LocalFiring;
}

/**
 * The last firing before and first firing after the transition's
 * affected wall band [loWall, hiWall). For a spring-forward gap the
 * band is the skipped hour, so the bracket is the last firing before
 * the gap and the first after it; for a fall-back fold the band is
 * the repeated hour. Both sides must be within three hours of the
 * band, else the schedule does not fire around this transition.
 */
function bracketFirings(
  firings: LocalFiring[],
  wallMillis: number[],
  loWall: number,
  hiWall: number,
): Bracket | null {
  let before: LocalFiring | null = null;
  let beforeWall = -Infinity;
  let after: LocalFiring | null = null;
  let afterWall = Infinity;
  for (let i = 0; i < firings.length; i += 1) {
    const wall = wallMillis[i] ?? 0;
    const firing = firings[i];
    if (firing === undefined) {
      continue;
    }
    if (wall < loWall && wall > beforeWall) {
      before = firing;
      beforeWall = wall;
    }
    if (wall >= hiWall && wall < afterWall) {
      after = firing;
      afterWall = wall;
    }
  }
  if (before === null || after === null) {
    return null;
  }
  if (loWall - beforeWall > THREE_HOURS_MILLIS || afterWall - hiWall > THREE_HOURS_MILLIS) {
    return null;
  }
  return { before, after };
}

/** Emits one INTERVAL_DRIFT per transition the schedule fires around. */
export function intervalDriftHazards(
  firings: LocalFiring[],
  expression: string,
  dialect: DialectId,
  zone: string,
  from: LocalFiring,
  to: LocalFiring,
  backend: TzBackend,
  idempotent: boolean,
): Hazard[] {
  const wallMillis = firings.map((firing) => wallMillisFromFields(firing));
  const cadence = nominalCadence(wallMillis);
  if (cadence === null) {
    return [];
  }
  const hazards: Hazard[] = [];
  for (const transition of windowTransitions(backend, zone, from, to)) {
    const boundaryA = transition.instant + transition.offsetBeforeSeconds * 1000;
    const boundaryB = transition.instant + transition.offsetAfterSeconds * 1000;
    const loWall = Math.min(boundaryA, boundaryB);
    const hiWall = Math.max(boundaryA, boundaryB);
    const bracket = bracketFirings(firings, wallMillis, loWall, hiWall);
    if (bracket === null) {
      continue;
    }
    hazards.push(
      makeHazard({
        kind: 'INTERVAL_DRIFT',
        expression,
        dialect,
        zone,
        intendedLocal: bracket.before,
        instants: [],
        causingTransition: {
          instant: transition.instant,
          offsetBeforeSeconds: transition.offsetBeforeSeconds,
          offsetAfterSeconds: transition.offsetAfterSeconds,
          deltaSeconds: transition.deltaSeconds,
        },
        idempotent,
        detail: {
          kind: 'INTERVAL_DRIFT',
          drift: {
            expectedIntervalMillis: cadence,
            actualIntervalMillis: cadence + Math.abs(transition.deltaSeconds) * 1000,
            before: bracket.before,
            after: bracket.after,
          },
        },
      }),
    );
  }
  return hazards;
}

src/hazard/zone-unstable.ts.source:
/**
 * ZONE_UNSTABLE: labels the region of a window that is a prediction
 * rather than a recorded fact. The concrete, checkable boundary is
 * the last transition in the zone's compiled table: firings past it
 * are governed by the POSIX footer, which extrapolates a DST rule
 * into the future. When the footer defines no DST (a constant
 * offset), extrapolation is exact and no label is warranted.
 *
 * Detecting a rule that changed in a recent tzdb release needs a diff
 * between tzdb versions, which is out of scope for this phase; that
 * reason is modeled in the type but not emitted here. See
 * DECISIONS.md, phase 4.
 */

import {
  parsePosixTz,
  parseTzif,
  readZoneFile,
  wallMillisFromFields,
} from '../tz/index';
import type { DialectId, LocalFiring } from '../cron/index';
import { makeHazard } from './build-hazard';
import type { Hazard } from './types';

interface FooterBoundary {
  lastTableTransition: number;
  footerHasDst: boolean;
}

function footerBoundary(zoneinfoRoot: string, zone: string): FooterBoundary | null {
  let data;
  try {
    data = parseTzif(readZoneFile(zoneinfoRoot, zone));
  } catch {
    return null;
  }
  if (data.transitionMillis.length === 0) {
    return null;
  }
  const last = data.transitionMillis[data.transitionMillis.length - 1] ?? null;
  if (last === null) {
    return null;
  }
  const posix = data.posixTzString === null ? null : parsePosixTz(data.posixTzString);
  return { lastTableTransition: last, footerHasDst: posix !== null && posix.dstStart !== null };
}

/**
 * Emits a single ZONE_UNSTABLE label when the window has firings past
 * the last recorded transition and the footer extrapolates a DST
 * rule. Returns nothing when no root was supplied, the zone cannot be
 * read, the footer is a constant offset, or no firing reaches the
 * predicted region.
 */
export function zoneUnstableHazards(
  firings: LocalFiring[],
  expression: string,
  dialect: DialectId,
  zone: string,
  zoneinfoRoot: string | undefined,
  idempotent: boolean,
): Hazard[] {
  if (zoneinfoRoot === undefined) {
    return [];
  }
  const boundary = footerBoundary(zoneinfoRoot, zone);
  if (boundary === null || !boundary.footerHasDst) {
    return [];
  }
  const firstBeyond = firings.find(
    (firing) => wallMillisFromFields(firing) >= boundary.lastTableTransition,
  );
  if (firstBeyond === undefined) {
    return [];
  }
  return [
    makeHazard({
      kind: 'ZONE_UNSTABLE',
      expression,
      dialect,
      zone,
      intendedLocal: firstBeyond,
      instants: [],
      causingTransition: null,
      idempotent,
      detail: {
        kind: 'ZONE_UNSTABLE',
        unstable: {
          reason: 'footer-extrapolation',
          lastTableTransitionInstant: boundary.lastTableTransition,
        },
      },
    }),
  ];
}

src/tz/civil-date.ts.source:
/**
 * Proleptic Gregorian calendar math on plain integers. Used to
 * convert local wall-clock fields to and from "wall milliseconds"
 * (the fields interpreted as if they were UTC) without going through
 * the host Date object, and to evaluate POSIX TZ day rules.
 *
 * The day-count algorithms are the standard branchless civil-date
 * conversions over an epoch of 1970-01-01.
 */

import type { LocalWallFields } from './types';

/** Milliseconds in one day. */
export const DAY_MILLIS = 86_400_000;

/** Returns true when the year is a Gregorian leap year. */
export function isLeapYear(year: number): boolean {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

/** Days in the given month (1 through 12) of the given year. */
export function daysInMonth(year: number, month: number): number {
  if (month === 2) {
    return isLeapYear(year) ? 29 : 28;
  }
  return [31, 0, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1] ?? 30;
}

/** Days since 1970-01-01 for a civil date; negative before 1970. */
export function daysFromCivil(year: number, month: number, day: number): number {
  const y = month <= 2 ? year - 1 : year;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const mp = (month + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + day - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

/** Civil date for a count of days since 1970-01-01. */
export function civilFromDays(days: number): {
  year: number;
  month: number;
  day: number;
} {
  const z = days + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor(
    (doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365,
  );
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const day = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const month = mp < 10 ? mp + 3 : mp - 9;
  return { year: month <= 2 ? y + 1 : y, month, day };
}

/** Day of week for a day count since 1970-01-01; 0 is Sunday. */
export function weekdayFromDays(days: number): number {
  const wd = (days + 4) % 7;
  return wd < 0 ? wd + 7 : wd;
}

/**
 * Encodes local wall-clock fields as wall milliseconds: the value a
 * UTC clock would read at the same year, month, day, and time.
 */
export function wallMillisFromFields(fields: LocalWallFields): number {
  const days = daysFromCivil(fields.year, fields.month, fields.day);
  return (
    days * DAY_MILLIS +
    fields.hour * 3_600_000 +
    fields.minute * 60_000 +
    (fields.second ?? 0) * 1000 +
    (fields.millisecond ?? 0)
  );
}

/** Decodes wall milliseconds back into local wall-clock fields. */
export function fieldsFromWallMillis(wallMillis: number): Required<LocalWallFields> {
  const days = Math.floor(wallMillis / DAY_MILLIS);
  let rest = wallMillis - days * DAY_MILLIS;
  const { year, month, day } = civilFromDays(days);
  const hour = Math.floor(rest / 3_600_000);
  rest -= hour * 3_600_000;
  const minute = Math.floor(rest / 60_000);
  rest -= minute * 60_000;
  const second = Math.floor(rest / 1000);
  return { year, month, day, hour, minute, second, millisecond: rest - second * 1000 };
}

src/tz/cross-check.ts.source:
/**
 * Differential cross-check of the two timezone backends. For each
 * zone, every transition instant and every offset on both sides must
 * agree exactly; any disagreement is a hard failure that identifies
 * the zone and the instant.
 *
 * The comparison runs in both directions. Every transition backend B
 * reads from the TZif table or footer is verified against backend
 * A's offsets one second before the instant and at the instant, so
 * the verification queries A's data directly and does not depend on
 * A's probe-scan granularity. Every transition backend A's scan
 * discovers must in turn exist in B's list with identical offsets,
 * which catches transitions missing from B.
 */

import type { TzBackend, ZoneTransition } from './types';

/** One point of disagreement between the backends. */
export interface CrossCheckDisagreement {
  /** Zone in which the backends disagree. */
  zone: string;
  /** Instant involved, UTC milliseconds, or null for count skew. */
  instant: number | null;
  /** Human-readable description of the disagreement. */
  detail: string;
}

/** Cross-check result for one zone. */
export interface ZoneCheckResult {
  /** The zone that was checked. */
  zone: string;
  /** Transitions found by backend A. */
  countA: number;
  /** Transitions found by backend B. */
  countB: number;
  /**
   * Transitions verified between the backends: every backend B
   * transition, each checked against backend A's offsets on both
   * sides of the instant. Backend A discoveries missing from B are
   * reported as disagreements on top of this count.
   */
  transitionsCompared: number;
  /** All disagreements found in this zone. */
  disagreements: CrossCheckDisagreement[];
}

/** Aggregate result of a cross-check run. */
export interface CrossCheckReport {
  /** Per-zone results in input order. */
  zoneResults: ZoneCheckResult[];
  /** Number of zones checked. */
  zonesChecked: number;
  /** Total transition pairs compared across all zones. */
  transitionsCompared: number;
  /** All disagreements across all zones. */
  disagreements: CrossCheckDisagreement[];
}

function iso(millis: number): string {
  return new Date(millis).toISOString();
}

/** Cross-checks a single zone over [startUtcMillis, endUtcMillis). */
export function crossCheckZone(
  backendA: TzBackend,
  backendB: TzBackend,
  zone: string,
  startUtcMillis: number,
  endUtcMillis: number,
): ZoneCheckResult {
  const listA = backendA.transitionsBetween(startUtcMillis, endUtcMillis, zone);
  const listB = backendB.transitionsBetween(startUtcMillis, endUtcMillis, zone);
  const disagreements: CrossCheckDisagreement[] = [];

  const byInstantB = new Map<number, ZoneTransition>();
  for (const b of listB) {
    byInstantB.set(b.instant, b);
  }

  for (const b of listB) {
    const beforeA = backendA.offsetAt(b.instant - 1000, zone).offsetSeconds;
    const afterA = backendA.offsetAt(b.instant, zone).offsetSeconds;
    if (beforeA !== b.offsetBeforeSeconds) {
      disagreements.push({
        zone,
        instant: b.instant,
        detail:
          `at ${iso(b.instant)}: offset before transition differs, ` +
          `A=${beforeA}s B=${b.offsetBeforeSeconds}s`,
      });
    }
    if (afterA !== b.offsetAfterSeconds) {
      disagreements.push({
        zone,
        instant: b.instant,
        detail:
          `at ${iso(b.instant)}: offset after transition differs, ` +
          `A=${afterA}s B=${b.offsetAfterSeconds}s`,
      });
    }
  }

  for (const a of listA) {
    const match = byInstantB.get(a.instant);
    if (match === undefined) {
      disagreements.push({
        zone,
        instant: a.instant,
        detail: `backend A finds a transition at ${iso(a.instant)} that backend B does not have`,
      });
    } else if (
      match.offsetBeforeSeconds !== a.offsetBeforeSeconds ||
      match.offsetAfterSeconds !== a.offsetAfterSeconds
    ) {
      disagreements.push({
        zone,
        instant: a.instant,
        detail:
          `at ${iso(a.instant)}: offsets differ, ` +
          `A=${a.offsetBeforeSeconds}s/${a.offsetAfterSeconds}s ` +
          `B=${match.offsetBeforeSeconds}s/${match.offsetAfterSeconds}s`,
      });
    }
  }

  return {
    zone,
    countA: listA.length,
    countB: listB.length,
    transitionsCompared: listB.length,
    disagreements,
  };
}

/** Options for {@link runCrossCheck}. */
export interface CrossCheckOptions {
  /** Backend A, conventionally the Intl backend. */
  backendA: TzBackend;
  /** Backend B, conventionally the TZif backend. */
  backendB: TzBackend;
  /** Zones to check. */
  zones: string[];
  /** Range start, UTC milliseconds inclusive. */
  startUtcMillis: number;
  /** Range end, UTC milliseconds exclusive. */
  endUtcMillis: number;
  /** Optional per-zone progress callback. */
  onZone?: (result: ZoneCheckResult) => void;
}

/** Runs the cross-check over every requested zone. */
export function runCrossCheck(options: CrossCheckOptions): CrossCheckReport {
  const zoneResults: ZoneCheckResult[] = [];
  const disagreements: CrossCheckDisagreement[] = [];
  let transitionsCompared = 0;
  for (const zone of options.zones) {
    const result = crossCheckZone(
      options.backendA,
      options.backendB,
      zone,
      options.startUtcMillis,
      options.endUtcMillis,
    );
    zoneResults.push(result);
    disagreements.push(...result.disagreements);
    transitionsCompared += result.transitionsCompared;
    options.onZone?.(result);
  }
  return {
    zoneResults,
    zonesChecked: zoneResults.length,
    transitionsCompared,
    disagreements,
  };
}

src/tz/intl-backend.ts.source:
/**
 * Backend A: resolves offsets through Intl.DateTimeFormat with
 * timeZoneName "longOffset" via formatToParts. Transitions are found
 * by probing the offset over the requested range and bisecting each
 * detected change down to one second, the granularity of tzdb
 * transition instants.
 *
 * Known limitation, by construction of the probe scan: a pair of
 * opposing transitions with zero net offset change that both fall
 * strictly inside one probe interval (7 days) is invisible to this
 * backend. The cross-check still catches such a pair whenever the
 * TZif backend records it, because every TZif transition is verified
 * against this backend's offsets on both sides of the instant.
 */

import type { OffsetInfo, TzBackend, ZoneTransition } from './types';

const PROBE_MILLIS = 7 * 86_400_000;
const SECOND_MILLIS = 1000;

type NameStyle = 'longOffset' | 'long' | 'short';

const formatterCache = new Map<string, Intl.DateTimeFormat>();

function formatter(zone: string, style: NameStyle): Intl.DateTimeFormat {
  const key = `${zone}�${style}`;
  let cached = formatterCache.get(key);
  if (cached === undefined) {
    cached = new Intl.DateTimeFormat('en-US', {
      timeZone: zone,
      timeZoneName: style,
      hour: 'numeric',
    });
    formatterCache.set(key, cached);
  }
  return cached;
}

function zoneNamePart(zone: string, style: NameStyle, millis: number): string {
  const parts = formatter(zone, style).formatToParts(new Date(millis));
  const part = parts.find((p) => p.type === 'timeZoneName');
  if (part === undefined) {
    throw new Error(`Intl returned no timeZoneName part for ${zone}`);
  }
  return part.value;
}

const LONG_OFFSET = /^GMT(?:([+-])(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/;

function parseLongOffsetSeconds(text: string): number {
  const normalized = text.replace('−', '-');
  const match = LONG_OFFSET.exec(normalized);
  if (match === null) {
    throw new Error(`unparseable longOffset value: ${text}`);
  }
  if (match[1] === undefined) {
    return 0;
  }
  const magnitude =
    Number(match[2]) * 3600 + Number(match[3]) * 60 + Number(match[4] ?? 0);
  return match[1] === '-' ? -magnitude : magnitude;
}

function offsetSecondsAt(millis: number, zone: string): number {
  return parseLongOffsetSeconds(zoneNamePart(zone, 'longOffset', millis));
}

/**
 * Marks an instant as DST when the zone's English long name contains
 * "Daylight" or "Summer". This is a heuristic: Intl exposes no DST
 * bit, and CLDR naming can disagree with the tzdb flag (Europe/Dublin
 * models winter as the DST variant in TZif while CLDR names summer
 * "Irish Standard Time"). Nothing in this codebase consumes isDst
 * for offset math or season logic; the flag is reported data only.
 */
function isDstAt(millis: number, zone: string): boolean {
  return /Daylight|Summer/.test(zoneNamePart(zone, 'long', millis));
}

function floorToSecond(millis: number): number {
  return Math.floor(millis / SECOND_MILLIS) * SECOND_MILLIS;
}

/**
 * Earliest second-aligned instant in (lo, hi] whose offset differs
 * from offsetAtLo, given that the offset at hi already differs.
 * Both bounds must be second-aligned.
 */
function bisectChange(
  zone: string,
  lo: number,
  offsetAtLo: number,
  hi: number,
): number {
  let low = lo;
  let high = hi;
  while (high - low > SECOND_MILLIS) {
    let mid = floorToSecond(low + (high - low) / 2);
    if (mid <= low) {
      mid = low + SECOND_MILLIS;
    }
    if (offsetSecondsAt(mid, zone) === offsetAtLo) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return high;
}

/** Creates the Intl backend. */
export function createIntlBackend(): TzBackend {
  const offsetAt = (instantUtcMillis: number, zone: string): OffsetInfo => ({
    offsetSeconds: offsetSecondsAt(instantUtcMillis, zone),
    abbreviation: zoneNamePart(zone, 'short', instantUtcMillis),
    isDst: isDstAt(instantUtcMillis, zone),
  });

  const transitionsBetween = (
    startUtcMillis: number,
    endUtcMillis: number,
    zone: string,
  ): ZoneTransition[] => {
    const out: ZoneTransition[] = [];
    let cursor = floorToSecond(startUtcMillis) - SECOND_MILLIS;
    let cursorOffset = offsetSecondsAt(cursor, zone);
    while (cursor < endUtcMillis) {
      const probe = Math.min(cursor + PROBE_MILLIS, floorToSecond(endUtcMillis));
      if (probe <= cursor) {
        break;
      }
      const probeOffset = offsetSecondsAt(probe, zone);
      if (probeOffset === cursorOffset) {
        cursor = probe;
        continue;
      }
      const instant = bisectChange(zone, cursor, cursorOffset, probe);
      const after = offsetSecondsAt(instant, zone);
      if (instant >= startUtcMillis && instant < endUtcMillis) {
        out.push({
          instant,
          offsetBeforeSeconds: cursorOffset,
          offsetAfterSeconds: after,
          deltaSeconds: after - cursorOffset,
        });
      }
      cursor = instant;
      cursorOffset = after;
    }
    return out;
  };

  return { name: 'intl', offsetAt, transitionsBetween };
}

