/**
 * Resolves a local wall-clock reading in a zone to a three-way
 * discriminated union: UNIQUE (one instant), NONEXISTENT (skipped by
 * a forward transition), or AMBIGUOUS (repeated by a backward
 * transition). The union is the product: no code path yields an
 * instant without forcing the caller to handle which case occurred.
 *
 * The resolution uses offsets and transitions only. The isDst flag
 * plays no role, so negative-DST zones (Europe/Dublin) resolve
 * correctly.
 */

import { DAY_MILLIS, daysInMonth, wallMillisFromFields } from './civil-date';
import { createTzifBackend } from './tzif-backend';
import type {
  LocalWallFields,
  TzBackend,
  WallClockResolution,
  ZoneTransition,
} from './types';

const WINDOW_MILLIS = 2 * DAY_MILLIS;

let defaultBackend: TzBackend | null = null;

function fallbackBackend(): TzBackend {
  if (defaultBackend === null) {
    defaultBackend = createTzifBackend();
  }
  return defaultBackend;
}

function validateFields(fields: LocalWallFields): void {
  const checks: [string, number, number, number][] = [
    ['month', fields.month, 1, 12],
    ['day', fields.day, 1, daysInMonth(fields.year, fields.month)],
    ['hour', fields.hour, 0, 23],
    ['minute', fields.minute, 0, 59],
    ['second', fields.second ?? 0, 0, 59],
    ['millisecond', fields.millisecond ?? 0, 0, 999],
  ];
  for (const [name, value, min, max] of checks) {
    if (!Number.isInteger(value) || value < min || value > max) {
      throw new RangeError(`${name} out of range: ${value}`);
    }
  }
}

interface Segment {
  startUtcMillis: number;
  endUtcMillis: number;
  offsetSeconds: number;
}

function segmentsAround(
  backend: TzBackend,
  zone: string,
  windowStart: number,
  windowEnd: number,
  transitions: ZoneTransition[],
): Segment[] {
  const segments: Segment[] = [];
  let cursor = windowStart;
  let offset = backend.offsetAt(windowStart, zone).offsetSeconds;
  for (const transition of transitions) {
    segments.push({ startUtcMillis: cursor, endUtcMillis: transition.instant, offsetSeconds: offset });
    cursor = transition.instant;
    offset = transition.offsetAfterSeconds;
  }
  segments.push({ startUtcMillis: cursor, endUtcMillis: windowEnd, offsetSeconds: offset });
  return segments;
}

/**
 * Resolves local wall-clock fields in an IANA zone. Uses the given
 * backend, defaulting to a shared TZif backend. Throws RangeError on
 * out-of-range fields and propagates backend errors for unknown
 * zones.
 */
export function resolveWallClock(
  fields: LocalWallFields,
  zone: string,
  backend: TzBackend = fallbackBackend(),
): WallClockResolution {
  validateFields(fields);
  const wall = wallMillisFromFields(fields);
  const windowStart = wall - WINDOW_MILLIS;
  const windowEnd = wall + WINDOW_MILLIS;
  const transitions = backend.transitionsBetween(windowStart, windowEnd, zone);
  const segments = segmentsAround(backend, zone, windowStart, windowEnd, transitions);

  const candidates: { instant: number; offsetSeconds: number }[] = [];
  for (const segment of segments) {
    const instant = wall - segment.offsetSeconds * 1000;
    if (instant >= segment.startUtcMillis && instant < segment.endUtcMillis) {
      candidates.push({ instant, offsetSeconds: segment.offsetSeconds });
    }
  }
  candidates.sort((a, b) => a.instant - b.instant);

  if (candidates.length === 1) {
    const only = candidates[0];
    if (only === undefined) {
      throw new Error('unreachable: candidate list of length 1 is empty');
    }
    return { kind: 'unique', instant: only.instant, offsetSeconds: only.offsetSeconds };
  }

  if (candidates.length === 0) {
    for (const transition of transitions) {
      const gapStartWallMillis = transition.instant + transition.offsetBeforeSeconds * 1000;
      const gapEndWallMillis = transition.instant + transition.offsetAfterSeconds * 1000;
      if (
        transition.deltaSeconds > 0 &&
        wall >= gapStartWallMillis &&
        wall < gapEndWallMillis
      ) {
        return {
          kind: 'nonexistent',
          transitionInstant: transition.instant,
          gapStartWallMillis,
          gapEndWallMillis,
          gapDurationMilliseconds: transition.deltaSeconds * 1000,
        };
      }
    }
    throw new Error(
      `no candidate instant and no covering gap for ${zone}; backend transitions inconsistent`,
    );
  }

  const first = candidates[0];
  const last = candidates[candidates.length - 1];
  if (first === undefined || last === undefined) {
    throw new Error('unreachable: multi-candidate list has no endpoints');
  }
  return {
    kind: 'ambiguous',
    candidateInstants: candidates.map((c) => c.instant),
    earlierInstant: first.instant,
    laterInstant: last.instant,
    foldDurationMilliseconds: (first.offsetSeconds - last.offsetSeconds) * 1000,
  };
}

src/tz/tzif-backend.ts.source:
/**
 * Backend B: resolves offsets and transitions by reading compiled
 * zoneinfo (TZif) files directly. Uses the 64-bit transition table
 * for instants the table covers and the POSIX TZ footer string for
 * extrapolation past the last recorded transition.
 */

import { civilFromDays, DAY_MILLIS } from './civil-date';
import { parsePosixTz, ruleInstantUtcMillis, type PosixTz } from './posix-tz';
import { parseTzif, type TzifData, type TzifType } from './tzif-parse';
import { readZoneFile, resolveZoneinfoRoot } from './zoneinfo-source';
import type { OffsetInfo, TzBackend, ZoneTransition } from './types';

/** Options for {@link createTzifBackend}. */
export interface TzifBackendOptions {
  /**
   * Zoneinfo root directory. Defaults to /usr/share/zoneinfo when
   * present, else the tzdata vendored with this package.
   */
  zoneinfoRoot?: string;
}

/** The TZif backend: a {@link TzBackend} plus its resolved root. */
export interface TzifBackend extends TzBackend {
  /** Absolute path of the zoneinfo root actually in use. */
  readonly zoneinfoRoot: string;
}

interface ZoneRecord {
  data: TzifData;
  posix: PosixTz | null;
}

interface FooterEvent {
  instant: number;
  toDst: boolean;
}

function typeInfo(type: TzifType): OffsetInfo {
  return {
    offsetSeconds: type.offsetSeconds,
    abbreviation: type.abbreviation,
    isDst: type.isDst,
  };
}

/** Index of the last transition at or before t, or -1. */
function lastTransitionIndex(transitions: number[], t: number): number {
  let lo = 0;
  let hi = transitions.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if ((transitions[mid] ?? Infinity) <= t) {
      found = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return found;
}

function utcYearOf(millis: number): number {
  return civilFromDays(Math.floor(millis / DAY_MILLIS)).year;
}

/**
 * DST start and end instants derived from the footer for the years
 * [fromYear, toYear], sorted ascending.
 */
function footerEvents(posix: PosixTz, fromYear: number, toYear: number): FooterEvent[] {
  if (
    posix.dstStart === null ||
    posix.dstEnd === null ||
    posix.dstOffsetSeconds === null
  ) {
    return [];
  }
  const events: FooterEvent[] = [];
  for (let year = fromYear; year <= toYear; year += 1) {
    events.push({
      instant: ruleInstantUtcMillis(posix.dstStart, year, posix.stdOffsetSeconds),
      toDst: true,
    });
    events.push({
      instant: ruleInstantUtcMillis(posix.dstEnd, year, posix.dstOffsetSeconds),
      toDst: false,
    });
  }
  return events.sort((a, b) => a.instant - b.instant);
}

function footerOffsetInfo(posix: PosixTz, t: number): OffsetInfo {
  const std: OffsetInfo = {
    offsetSeconds: posix.stdOffsetSeconds,
    abbreviation: posix.stdAbbreviation,
    isDst: false,
  };
  if (posix.dstAbbreviation === null || posix.dstOffsetSeconds === null) {
    return std;
  }
  const dst: OffsetInfo = {
    offsetSeconds: posix.dstOffsetSeconds,
    abbreviation: posix.dstAbbreviation,
    isDst: true,
  };
  const year = utcYearOf(t);
  const events = footerEvents(posix, year - 1, year + 1);
  let inDst: boolean | null = null;
  for (const event of events) {
    if (event.instant <= t) {
      inDst = event.toDst;
    }
  }
  if (inDst === null) {
    const first = events[0];
    inDst = first === undefined ? false : !first.toDst;
  }
  return inDst ? dst : std;
}

/**
 * Creates the TZif-file backend. Zone files are parsed once and
 * cached for the lifetime of the backend.
 */
export function createTzifBackend(options: TzifBackendOptions = {}): TzifBackend {
  const root = resolveZoneinfoRoot(options.zoneinfoRoot);
  const cache = new Map<string, ZoneRecord>();

  const load = (zone: string): ZoneRecord => {
    const cached = cache.get(zone);
    if (cached !== undefined) {
      return cached;
    }
    const data = parseTzif(readZoneFile(root, zone));
    const posix = data.posixTzString === null ? null : parsePosixTz(data.posixTzString);
    const record: ZoneRecord = { data, posix };
    cache.set(zone, record);
    return record;
  };

  const typeAtIndex = (data: TzifData, transitionIndex: number): TzifType => {
    const typeIndex =
      transitionIndex === -1
        ? data.firstTypeIndex
        : (data.transitionTypes[transitionIndex] ?? data.firstTypeIndex);
    const type = data.types[typeIndex];
    if (type === undefined) {
      throw new Error(`TZif type index ${typeIndex} out of range`);
    }
    return type;
  };

  const offsetAt = (instantUtcMillis: number, zone: string): OffsetInfo => {
    const { data, posix } = load(zone);
    const last = data.transitionMillis[data.transitionMillis.length - 1];
    const pastTable = last === undefined || instantUtcMillis >= last;
    if (pastTable && posix !== null) {
      return footerOffsetInfo(posix, instantUtcMillis);
    }
    const index = lastTransitionIndex(data.transitionMillis, instantUtcMillis);
    return typeInfo(typeAtIndex(data, index));
  };

  const transitionsBetween = (
    startUtcMillis: number,
    endUtcMillis: number,
    zone: string,
  ): ZoneTransition[] => {
    const { data, posix } = load(zone);
    const out: ZoneTransition[] = [];
    for (let i = 0; i < data.transitionMillis.length; i += 1) {
      const instant = data.transitionMillis[i];
      if (instant === undefined || instant < startUtcMillis) {
        continue;
      }
      if (instant >= endUtcMillis) {
        break;
      }
      const before = typeAtIndex(data, i - 1).offsetSeconds;
      const after = typeAtIndex(data, i).offsetSeconds;
      if (before !== after) {
        out.push({
          instant,
          offsetBeforeSeconds: before,
          offsetAfterSeconds: after,
          deltaSeconds: after - before,
        });
      }
    }
    const last = data.transitionMillis[data.transitionMillis.length - 1] ?? -Infinity;
    if (posix !== null && endUtcMillis > last) {
      const fromYear = utcYearOf(Math.max(startUtcMillis, last)) - 1;
      const toYear = utcYearOf(endUtcMillis) + 1;
      const dstOffset = posix.dstOffsetSeconds ?? posix.stdOffsetSeconds;
      for (const event of footerEvents(posix, fromYear, toYear)) {
        if (
          event.instant <= last ||
          event.instant < startUtcMillis ||
          event.instant >= endUtcMillis
        ) {
          continue;
        }
        const before = event.toDst ? posix.stdOffsetSeconds : dstOffset;
        const after = event.toDst ? dstOffset : posix.stdOffsetSeconds;
        if (before !== after) {
          out.push({
            instant: event.instant,
            offsetBeforeSeconds: before,
            offsetAfterSeconds: after,
            deltaSeconds: after - before,
          });
        }
      }
    }
    return out;
  };

  return {
    name: 'tzif',
    zoneinfoRoot: root,
    offsetAt,
    transitionsBetween,
  };
}

src/tz/tzif-parse.ts.source:
/**
 * Binary parser for TZif files (RFC 8536), the compiled zoneinfo
 * format produced by zic. Reads version 2 and later files: the
 * 32-bit version 1 block is skipped, the 64-bit block supplies the
 * transition table, leap-second records are ignored, and the POSIX
 * TZ footer string is captured for extrapolation past the last
 * recorded transition.
 */

/** One local-time type from a TZif file. */
export interface TzifType {
  /** UTC offset in seconds, east positive. */
  offsetSeconds: number;
  /** Daylight-saving flag exactly as stored in the file. */
  isDst: boolean;
  /** Zone designation, for example "EST" or "+11". */
  abbreviation: string;
}

/** Parsed contents of one TZif file's 64-bit data block. */
export interface TzifData {
  /** TZif format version character: "2", "3", or "4". */
  version: string;
  /** Transition instants in UTC milliseconds, ascending. */
  transitionMillis: number[];
  /** Index into `types` for the interval after each transition. */
  transitionTypes: number[];
  /** All local-time types defined by the file. */
  types: TzifType[];
  /** Index of the type in effect before the first transition. */
  firstTypeIndex: number;
  /** POSIX TZ footer string, or null when the footer is empty. */
  posixTzString: string | null;
}

interface Header {
  version: string;
  isutcnt: number;
  isstdcnt: number;
  leapcnt: number;
  timecnt: number;
  typecnt: number;
  charcnt: number;
}

function readHeader(view: DataView, at: number): Header {
  const magic = String.fromCharCode(
    view.getUint8(at),
    view.getUint8(at + 1),
    view.getUint8(at + 2),
    view.getUint8(at + 3),
  );
  if (magic !== 'TZif') {
    throw new Error('not a TZif file: bad magic');
  }
  const versionByte = view.getUint8(at + 4);
  return {
    version: versionByte === 0 ? '1' : String.fromCharCode(versionByte),
    isutcnt: view.getUint32(at + 20),
    isstdcnt: view.getUint32(at + 24),
    leapcnt: view.getUint32(at + 28),
    timecnt: view.getUint32(at + 32),
    typecnt: view.getUint32(at + 36),
    charcnt: view.getUint32(at + 40),
  };
}

const HEADER_BYTES = 44;

function dataBlockBytes(header: Header, timeBytes: number): number {
  return (
    header.timecnt * timeBytes +
    header.timecnt +
    header.typecnt * 6 +
    header.charcnt +
    header.leapcnt * (timeBytes + 4) +
    header.isstdcnt +
    header.isutcnt
  );
}

function decodeAscii(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => String.fromCharCode(b)).join('');
}

function abbreviationAt(chars: string, index: number): string {
  const end = chars.indexOf('\0', index);
  return end === -1 ? chars.slice(index) : chars.slice(index, end);
}

/**
 * Parses a TZif version 2 or later file. Throws on version 1 files
 * (no 64-bit block) and on structurally invalid input.
 */
export function parseTzif(buffer: Uint8Array): TzifData {
  const view = new DataView(buffer.buffer, buffer.byteOffset, buffer.byteLength);
  const v1Header = readHeader(view, 0);
  if (v1Header.version === '1') {
    throw new Error('TZif version 1 file has no 64-bit data block');
  }
  const v2Start = HEADER_BYTES + dataBlockBytes(v1Header, 4);
  const header = readHeader(view, v2Start);
  let at = v2Start + HEADER_BYTES;

  const transitionMillis: number[] = [];
  for (let i = 0; i < header.timecnt; i += 1) {
    transitionMillis.push(Number(view.getBigInt64(at)) * 1000);
    at += 8;
  }
  const transitionTypes: number[] = [];
  for (let i = 0; i < header.timecnt; i += 1) {
    transitionTypes.push(view.getUint8(at));
    at += 1;
  }
  const rawTypes: { offsetSeconds: number; isDst: boolean; desigIndex: number }[] = [];
  for (let i = 0; i < header.typecnt; i += 1) {
    rawTypes.push({
      offsetSeconds: view.getInt32(at),
      isDst: view.getUint8(at + 4) !== 0,
      desigIndex: view.getUint8(at + 5),
    });
    at += 6;
  }
  const chars = decodeAscii(buffer.subarray(at, at + header.charcnt));
  at += header.charcnt;
  at += header.leapcnt * 12 + header.isstdcnt + header.isutcnt;

  const types: TzifType[] = rawTypes.map((raw) => ({
    offsetSeconds: raw.offsetSeconds,
    isDst: raw.isDst,
    abbreviation: abbreviationAt(chars, raw.desigIndex),
  }));

  let posixTzString: string | null = null;
  if (at < buffer.byteLength && view.getUint8(at) === 0x0a) {
    const rest = buffer.subarray(at + 1);
    const newline = rest.indexOf(0x0a);
    const footer = decodeAscii(newline === -1 ? rest : rest.subarray(0, newline));
    posixTzString = footer.length > 0 ? footer : null;
  }

  /*
   * RFC 8536 section 3.2: "Local time for timestamps before the
   * first transition is specified by the first time type (time
   * type 0)." Fetched 2026-07-25:
   * https://www.rfc-editor.org/rfc/rfc8536
   */
  return {
    version: header.version,
    transitionMillis,
    transitionTypes,
    types,
    firstTypeIndex: 0,
    posixTzString,
  };
}

src/tz/versions.ts.source:
/**
 * Exposes the tzdb version of each data source separately: the copy
 * bundled with the JavaScript runtime's ICU (used by the Intl
 * backend) and the compiled zoneinfo tree (used by the TZif
 * backend). A verdict computed against a stale tzdb is worth
 * nothing, so disagreement between the two must be surfaced loudly.
 */

import { readZoneinfoVersion, resolveZoneinfoRoot } from './zoneinfo-source';

/** tzdb versions of the two independent data sources. */
export interface TzdbVersions {
  /** tzdb version bundled with the runtime's ICU, or null if unknown. */
  intlTzdbVersion: string | null;
  /** tzdb version of the zoneinfo root, or null if undeclared. */
  zoneinfoTzdbVersion: string | null;
  /** The zoneinfo root the version was read from. */
  zoneinfoRoot: string;
}

/**
 * Reads both tzdb versions. The Intl side comes from
 * process.versions.tz; the zoneinfo side from the root's +VERSION
 * file or tzdata.zi header.
 */
export function tzdbVersions(zoneinfoRoot?: string): TzdbVersions {
  const root = resolveZoneinfoRoot(zoneinfoRoot);
  return {
    intlTzdbVersion: process.versions.tz ?? null,
    zoneinfoTzdbVersion: readZoneinfoVersion(root),
    zoneinfoRoot: root,
  };
}

/**
 * Returns a loud multi-line warning when the two tzdb versions
 * disagree or either is unknown, or null when they match.
 */
export function tzdbVersionWarning(versions: TzdbVersions): string | null {
  const { intlTzdbVersion, zoneinfoTzdbVersion } = versions;
  if (intlTzdbVersion === null || zoneinfoTzdbVersion === null) {
    return [
      'WARNING: a tzdb version could not be determined.',
      `  Intl (ICU) tzdb: ${intlTzdbVersion ?? 'unknown'}`,
      `  zoneinfo tzdb:   ${zoneinfoTzdbVersion ?? 'unknown'} (${versions.zoneinfoRoot})`,
      '  Results cannot be tied to a known tzdb release.',
    ].join('\n');
  }
  if (intlTzdbVersion === zoneinfoTzdbVersion) {
    return null;
  }
  return [
    '################################################################',
    'WARNING: tzdb VERSION MISMATCH between the two data sources.',
    `  Intl (ICU) tzdb: ${intlTzdbVersion}`,
    `  zoneinfo tzdb:   ${zoneinfoTzdbVersion} (${versions.zoneinfoRoot})`,
    '  One of these databases is stale. Offsets and transitions that',
    '  changed between the releases WILL differ between backends, and',
    '  any verdict computed against the stale side is worth nothing.',
    '################################################################',
  ].join('\n');
}

src/tz/zoneinfo-source.ts.source:
/**
 * Locates compiled zoneinfo files. The root is configurable; the
 * default is the system path /usr/share/zoneinfo, falling back to
 * the tzdata vendored in this package (vendor/zoneinfo, compiled
 * with zic from an IANA release) so the TZif backend works on
 * systems without system zoneinfo.
 */

import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/** The conventional system zoneinfo directory. */
export const SYSTEM_ZONEINFO_ROOT = '/usr/share/zoneinfo';

/**
 * Directory names inside a zoneinfo root that do not contain
 * ordinary zones: "right" holds leap-second-adjusted variants and
 * "posix" duplicates the default set.
 */
const EXCLUDED_DIRS = new Set(['right', 'posix']);

/**
 * Absolute path of the vendored zoneinfo directory shipped with this
 * package, or null when it cannot be located. The directory is found
 * by walking upward from this module, which works from both src/
 * (tsx) and dist/ (built) layouts.
 */
export function vendoredZoneinfoRoot(): string | null {
  let dir = path.dirname(fileURLToPath(import.meta.url));
  for (let depth = 0; depth < 6; depth += 1) {
    const candidate = path.join(dir, 'vendor', 'zoneinfo');
    if (existsSync(candidate)) {
      return candidate;
    }
    const parent = path.dirname(dir);
    if (parent === dir) {
      break;
    }
    dir = parent;
  }
  return null;
}

/**
 * Resolves the zoneinfo root to use: the explicit override when
 * given, else the system path when present, else the vendored copy.
 * Throws when no root can be found.
 */
export function resolveZoneinfoRoot(explicitRoot?: string): string {
  if (explicitRoot !== undefined) {
    if (!existsSync(explicitRoot)) {
      throw new Error(`zoneinfo root does not exist: ${explicitRoot}`);
    }
    return explicitRoot;
  }
  if (existsSync(SYSTEM_ZONEINFO_ROOT)) {
    return SYSTEM_ZONEINFO_ROOT;
  }
  const vendored = vendoredZoneinfoRoot();
  if (vendored !== null) {
    return vendored;
  }
  throw new Error(
    `no zoneinfo root: ${SYSTEM_ZONEINFO_ROOT} is absent and no vendored copy was found`,
  );
}

/**
 * Reads one zone's TZif file from the root. Rejects zone names that
 * would escape the root. Throws when the file does not exist.
 */
export function readZoneFile(root: string, zone: string): Uint8Array {
  if (zone.includes('..') || path.isAbsolute(zone)) {
    throw new Error(`invalid zone name: ${zone}`);
  }
  return readFileSync(path.join(root, zone));
}

function isTzifFile(filePath: string): boolean {
  try {
    const fd = readFileSync(filePath);
    return (
      fd.length >= 4 &&
      fd[0] === 0x54 &&
      fd[1] === 0x5a &&
      fd[2] === 0x69 &&
      fd[3] === 0x66
    );
  } catch {
    return false;
  }
}

/**
 * Lists every zone under the root whose file starts with the TZif
 * magic, as slash-separated names sorted ascending. Leap-second and
 * duplicate directories are excluded.
 */
export function listZones(root: string): string[] {
  const zones: string[] = [];
  const walk = (relative: string): void => {
    const absolute = path.join(root, relative);
    for (const entry of readdirSync(absolute)) {
      const relPath = relative === '' ? entry : `${relative}/${entry}`;
      if (relative === '' && EXCLUDED_DIRS.has(entry)) {
        continue;
      }
      const absPath = path.join(root, relPath);
      const stat = statSync(absPath);
      if (stat.isDirectory()) {
        walk(relPath);
      } else if (stat.isFile() && isTzifFile(absPath)) {
        zones.push(relPath);
      }
    }
  };
  walk('');
  return zones.sort();
}

/**
 * Reads the tzdb version of a zoneinfo root from its +VERSION file
 * or from the first line of tzdata.zi. Returns null when neither
 * source is present.
 */
export function readZoneinfoVersion(root: string): string | null {
  try {
    return readFileSync(path.join(root, '+VERSION'), 'utf8').trim();
  } catch {
    // fall through to tzdata.zi
  }
  try {
    const firstLine = readFileSync(path.join(root, 'tzdata.zi'), 'utf8').split('\n', 1)[0] ?? '';
    const match = /^#\s*version\s+(\S+)/.exec(firstLine);
    return match?.[1] ?? null;
  } catch {
    return null;
  }
}

src/hazard/build-hazard.ts.source:
/**
 * Assembles a {@link Hazard} from its parts, filling in the two
 * derived fields every hazard shares: the stable id (a hash of the
 * identity tuple) and the severity (from the kind and the schedule's
 * idempotence). Keeping this in one place means those two fields are
 * computed identically for every detector.
 */

import type { DialectId, LocalFiring } from '../cron/index';
import { hazardId } from './hazard-id';
import { severityFor } from './severity';
import type { CausingTransition, Hazard, HazardDetail, HazardKind } from './types';

/** Everything needed to build a hazard except its derived fields. */
export interface HazardDraft {
  /** Classification. */
  kind: HazardKind;
  /** Source expression. */
  expression: string;
  /** Dialect id. */
  dialect: DialectId;
  /** IANA zone. */
  zone: string;
  /** Intended local firing time (day at 00:00:00 for day-level hazards). */
  intendedLocal: LocalFiring;
  /** Resolved UTC instants. */
  instants: number[];
  /** Causing transition, or null. */
  causingTransition: CausingTransition | null;
  /** Kind-specific payload. */
  detail: HazardDetail;
  /** Whether the scheduled work is idempotent. */
  idempotent: boolean;
}

/** Builds a hazard, computing its stable id and severity. */
export function makeHazard(draft: HazardDraft): Hazard {
  return {
    id: hazardId({
      expression: draft.expression,
      dialect: draft.dialect,
      zone: draft.zone,
      intendedLocal: draft.intendedLocal,
      kind: draft.kind,
    }),
    kind: draft.kind,
    severity: severityFor(draft.kind, draft.idempotent),
    expression: draft.expression,
    dialect: draft.dialect,
    zone: draft.zone,
    intendedLocal: draft.intendedLocal,
    instants: draft.instants,
    causingTransition: draft.causingTransition,
    detail: draft.detail,
  };
}

src/hazard/hazard-id.ts.source:
/**
 * Stable hazard identity. The id is a hash of the tuple that defines
 * a hazard's meaning: expression, dialect, zone, intended local time,
 * and classification. It does not depend on resolved instants,
 * severity, or any field that a tzdb update or a code refactor might
 * shift, so a hazard keeps the same id across runs and can be
 * baselined and suppressed in CI. A test pins a known id literal so a
 * future change to this hash fails loudly.
 */

import { createHash } from 'node:crypto';
import type { LocalFiring } from '../cron/index';
import type { HazardKind } from './types';

/** Formats a local firing as a fixed-width, zone-free timestamp. */
export function formatLocal(local: LocalFiring): string {
  const p = (n: number, width = 2): string => String(n).padStart(width, '0');
  return (
    `${p(local.year, 4)}-${p(local.month)}-${p(local.day)}` +
    `T${p(local.hour)}:${p(local.minute)}:${p(local.second)}`
  );
}

/** The identity tuple hashed into a hazard id. */
export interface HazardIdentity {
  /** Source expression. */
  expression: string;
  /** Dialect id. */
  dialect: string;
  /** IANA zone. */
  zone: string;
  /** Intended local firing time. */
  intendedLocal: LocalFiring;
  /** Classification. */
  kind: HazardKind;
}

/**
 * Computes the stable hazard id: the first 16 hex characters of the
 * SHA-256 of the identity tuple. Only the expression can contain a
 * space; every following field (dialect, zone, the fixed-width local
 * timestamp, kind) is space-free, so the space join is unambiguous.
 * Prefixed with "hz_" so it reads as an id in output and baselines.
 */
export function hazardId(identity: HazardIdentity): string {
  const canonical = [
    identity.expression,
    identity.dialect,
    identity.zone,
    formatLocal(identity.intendedLocal),
    identity.kind,
  ].join('�');
  const digest = createHash('sha256').update(canonical, 'utf8').digest('hex');
  return `hz_${digest.slice(0, 16)}`;
}

src/hazard/per-firing.ts.source:
/**
 * Per-firing hazards for point schedules: a firing that lands in a
 * spring-forward gap is SKIPPED, and one that lands in a fall-back
 * fold is DOUBLED. Interval-like schedules do not use this path;
 * their transition effects are reported as INTERVAL_DRIFT instead.
 */

import type { TzBackend } from '../tz/index';
import type { ResolvedFiring } from './resolve-firings';
import { foldTransition, transitionAtInstant } from './transitions';
import type { Hazard } from './types';
import { makeHazard } from './build-hazard';

/** Classifies SKIPPED and DOUBLED firings for a point schedule. */
export function perFiringHazards(
  resolved: ResolvedFiring[],
  expression: string,
  dialect: Hazard['dialect'],
  zone: string,
  backend: TzBackend,
  idempotent: boolean,
): Hazard[] {
  const hazards: Hazard[] = [];
  for (const firing of resolved) {
    const resolution = firing.resolution;
    if (resolution.kind === 'nonexistent') {
      hazards.push(
        makeHazard({
          kind: 'SKIPPED',
          expression,
          dialect,
          zone,
          intendedLocal: firing.local,
          instants: [],
          causingTransition: transitionAtInstant(backend, zone, resolution.transitionInstant),
          idempotent,
          detail: {
            kind: 'SKIPPED',
            skipped: {
              gapStartWallMillis: resolution.gapStartWallMillis,
              gapEndWallMillis: resolution.gapEndWallMillis,
              gapDurationMillis: resolution.gapDurationMilliseconds,
            },
          },
        }),
      );
    } else if (resolution.kind === 'ambiguous') {
      hazards.push(
        makeHazard({
          kind: 'DOUBLED',
          expression,
          dialect,
          zone,
          intendedLocal: firing.local,
          instants: [resolution.earlierInstant, resolution.laterInstant],
          causingTransition: foldTransition(
            backend,
            zone,
            resolution.earlierInstant,
            resolution.laterInstant,
          ),
          idempotent,
          detail: {
            kind: 'DOUBLED',
            doubled: { foldDurationMillis: resolution.foldDurationMilliseconds },
          },
        }),
      );
    }
  }
  return hazards;
}

src/hazard/resolve-firings.ts.source:
/**
 * Bridges the enumerator and the resolver: turns intended wall-clock
 * firings into resolved firings, each carrying its wall-milliseconds
 * key and the three-way resolution. Detectors that need to know
 * whether individual firings exist, double, or vanish consume this.
 */

import { enumerate, type CronAst, type LocalFiring } from '../cron/index';
import {
  resolveWallClock,
  wallMillisFromFields,
  type TzBackend,
  type WallClockResolution,
} from '../tz/index';

/** An intended firing paired with its wall key and resolution. */
export interface ResolvedFiring {
  /** Intended local firing time. */
  local: LocalFiring;
  /** The local fields encoded as wall milliseconds. */
  wallMillis: number;
  /** How the local time resolves in the zone. */
  resolution: WallClockResolution;
}

/** Enumerates intended firings across the window, in wall order. */
export function enumerateFirings(
  ast: CronAst,
  zone: string,
  from: LocalFiring,
  to: LocalFiring,
): LocalFiring[] {
  return enumerate(ast, { zone, from, to });
}

/** Resolves each intended firing through the timezone engine. */
export function resolveFirings(
  firings: LocalFiring[],
  zone: string,
  backend: TzBackend,
): ResolvedFiring[] {
  return firings.map((local) => ({
    local,
    wallMillis: wallMillisFromFields(local),
    resolution: resolveWallClock(local, zone, backend),
  }));
}

src/hazard/severity.ts.source:
/**
 * Severity assignment for hazards. The reasoning behind the ordering
 * is recorded in DECISIONS.md; the short version is that a double run
 * of non-idempotent work corrupts state, while a skip usually only
 * delays, so DOUBLED on non-idempotent work outranks SKIPPED.
 * Idempotence cannot be read off a cron line, so it is an explicit
 * per-schedule flag defaulting to false (doubles treated as severe).
 */

import type { HazardKind, Severity } from './types';

const RANK: Record<Severity, number> = {
  info: 0,
  low: 1,
  medium: 2,
  high: 3,
  critical: 4,
};

/** Numeric rank of a severity, higher being more severe. */
export function severityRank(severity: Severity): number {
  return RANK[severity];
}

/**
 * Assigns severity from the hazard kind and whether the scheduled
 * work is idempotent.
 *
 * - DOUBLED: critical when not idempotent (a duplicate run can
 *   corrupt state), low when idempotent (the duplicate is harmless).
 * - SKIPPED: high. A missed run is serious but usually recoverable by
 *   a delayed or manual run, and it never corrupts state.
 * - COUNT_ANOMALY: high. A calendar day that does not exist means a
 *   daily job silently never runs that day, which is easy to miss.
 * - INTERVAL_DRIFT: medium. Cadence stretches or compresses across
 *   the transition but no single run is lost or duplicated.
 * - ZONE_UNSTABLE: info. Not a fault, a label: the region is a
 *   prediction from POSIX extrapolation, not a recorded fact.
 */
export function severityFor(kind: HazardKind, idempotent: boolean): Severity {
  switch (kind) {
    case 'DOUBLED':
      return idempotent ? 'low' : 'critical';
    case 'SKIPPED':
      return 'high';
    case 'COUNT_ANOMALY':
      return 'high';
    case 'INTERVAL_DRIFT':
      return 'medium';
    case 'ZONE_UNSTABLE':
      return 'info';
  }
}

src/hazard/transitions.ts.source:
/**
 * Helpers for locating offset transitions relevant to a hazard. All
 * timezone access for the hazard classifier funnels through here.
 */

import { wallMillisFromFields, type TzBackend, type ZoneTransition } from '../tz/index';
import type { LocalFiring } from '../cron/index';
import type { CausingTransition } from './types';

const DAY_MILLIS = 86_400_000;

function toCausing(transition: ZoneTransition): CausingTransition {
  return {
    instant: transition.instant,
    offsetBeforeSeconds: transition.offsetBeforeSeconds,
    offsetAfterSeconds: transition.offsetAfterSeconds,
    deltaSeconds: transition.deltaSeconds,
  };
}

/**
 * The transition active at an exact instant, or null. Transitions are
 * half-open [start, next), so a transition whose instant equals the
 * query is returned by a one-millisecond window.
 */
export function transitionAtInstant(
  backend: TzBackend,
  zone: string,
  instant: number,
): CausingTransition | null {
  const found = backend.transitionsBetween(instant, instant + 1, zone);
  const first = found[0];
  return first === undefined ? null : toCausing(first);
}

/**
 * The backward transition responsible for an ambiguous (folded) local
 * time, searched between the two candidate instants.
 */
export function foldTransition(
  backend: TzBackend,
  zone: string,
  earlierInstant: number,
  laterInstant: number,
): CausingTransition | null {
  const found = backend.transitionsBetween(earlierInstant, laterInstant + 1, zone);
  for (const transition of found) {
    if (transition.deltaSeconds < 0) {
      return toCausing(transition);
    }
  }
  return null;
}

/**
 * All transitions whose instant could fall inside the wall window
 * [from, to], padded so a transition near either edge is included.
 * The wall bounds are used as approximate UTC bounds; the padding of
 * two days covers the largest real offset.
 */
export function windowTransitions(
  backend: TzBackend,
  zone: string,
  from: LocalFiring,
  to: LocalFiring,
): ZoneTransition[] {
  const start = wallMillisFromFields(from) - 2 * DAY_MILLIS;
  const end = wallMillisFromFields(to) + 2 * DAY_MILLIS;
  return backend.transitionsBetween(start, end, zone);
}

tests/hazard/zone-and-null.test.ts.source:
import { beforeAll, describe, expect, test } from 'vitest';
import { parse } from '../../src/cron/index';
import type { DialectId, LocalFiring } from '../../src/cron/index';
import { classifyHazards } from '../../src/hazard/index';
import type { Hazard } from '../../src/hazard/index';
import { createTzifBackend, vendoredZoneinfoRoot, type TzifBackend } from '../../src/tz/index';

const root = vendoredZoneinfoRoot();
if (root === null) {
  throw new Error('vendored zoneinfo not found; run the phase 2 vendoring step');
}
const ROOT: string = root;

let backend: TzifBackend;
beforeAll(() => {
  backend = createTzifBackend({ zoneinfoRoot: ROOT });
});

const midnight = (year: number): LocalFiring => ({ year, month: 1, day: 1, hour: 0, minute: 0, second: 0 });

function classify(expression: string, dialect: DialectId, zone: string, fromYear: number, toYear: number): Hazard[] {
  const parsed = parse(expression, dialect);
  if (!parsed.ok) {
    throw new Error(`parse failed: ${JSON.stringify(parsed.errors)}`);
  }
  return classifyHazards(parsed.ast, backend, {
    expression,
    dialect,
    zone,
    from: midnight(fromYear),
    to: midnight(toYear),
    zoneinfoRoot: ROOT,
  });
}

describe('null test: UTC schedules produce zero hazards', () => {
  const schedules: [string, DialectId][] = [
    ['*/15 * * * *', 'vixie'],
    ['30 2 * * *', 'vixie'],
    ['0 0 * * *', 'vixie'],
    ['30 5 * * 1-5', 'github-actions'],
  ];
  const utcZones = ['UTC', 'Etc/UTC'];

  test.each(schedules)('%s in %s dialect yields no hazards in any UTC zone', (expression, dialect) => {
    for (const zone of utcZones) {
      const hazards = classify(expression, dialect, zone, 2024, 2026);
      expect(hazards, `${expression} in ${zone}`).toEqual([]);
    }
  });
});

describe('ZONE_UNSTABLE labels predicted regions past the last recorded transition', () => {
  test('a daily job the year after New York\'s last table transition is labeled footer-extrapolation', () => {
    const hazards = classify('0 12 * * *', 'vixie', 'America/New_York', 2038, 2039);
    const unstable = hazards.filter((hazard) => hazard.kind === 'ZONE_UNSTABLE');
    expect(unstable).toHaveLength(1);
    const hazard = unstable[0];
    expect(hazard?.severity).toBe('info');
    expect(hazard?.detail.kind === 'ZONE_UNSTABLE' && hazard.detail.unstable.reason).toBe('footer-extrapolation');
    expect(hazard?.detail.kind === 'ZONE_UNSTABLE' && hazard.detail.unstable.lastTableTransitionInstant).toBe(
      Date.UTC(2037, 10, 1, 6, 0),
    );
  });

  test('a constant-offset zone past its last transition is not labeled unstable (extrapolation is exact)', () => {
    const hazards = classify('0 12 * * *', 'vixie', 'Asia/Tehran', 2030, 2031);
    expect(hazards.filter((hazard) => hazard.kind === 'ZONE_UNSTABLE')).toEqual([]);
  });
});

